import Decimal from 'decimal.js';

// Isolated Decimal constructor: 40 significant digits is far beyond any asset's `decimals`,
// so +, - and * on amounts are exact. ROUND_DOWN only matters for explicit display rounding.
export const D = Decimal.clone({ precision: 40, rounding: Decimal.ROUND_DOWN });
export type Dec = Decimal;

// API format: digits, optional dot + digits, no leading zeros. ".5", "1.", "05", "1e-3" are invalid.
const USER_AMOUNT_RE = /^(0|[1-9]\d*)(\.\d+)?$/;
// Server data is trusted less strictly (we only need it to be a plain non-negative decimal string).
const SERVER_DECIMAL_RE = /^\d+(\.\d+)?$/;

export function parseServerDecimal(value: unknown, label = 'value'): Dec {
  if (typeof value !== 'string' || !SERVER_DECIMAL_RE.test(value)) {
    throw new Error(`Invalid decimal string for ${label}`);
  }
  return new D(value);
}

/** Canonical plain-notation string (never exponent form, no trailing zeros). */
export function plain(value: Dec | string): string {
  return new D(value).toFixed();
}

export type AmountError = 'EMPTY' | 'FORMAT' | 'PRECISION' | 'BELOW_MIN' | 'ABOVE_AVAILABLE';

export type AmountCheck =
  | { ok: true; amount: Dec; text: string }
  | { ok: false; error: AmountError; message: string };

export interface AmountRules {
  decimals: number;
  minAmount: string;
  available: string;
}

/** Mirrors the documented API rules: format, <= decimals places, minAmount <= amount <= available. */
export function validateAmount(input: string, rules: AmountRules): AmountCheck {
  const text = input.trim();
  if (text === '') return { ok: false, error: 'EMPTY', message: 'Enter an amount' };
  if (!USER_AMOUNT_RE.test(text)) {
    return {
      ok: false,
      error: 'FORMAT',
      message: 'Use digits with an optional dot, e.g. 0.5 or 12 (no leading zeros, no ".5", "1." or exponents)',
    };
  }
  const fraction = text.split('.')[1] ?? '';
  if (fraction.length > rules.decimals) {
    return { ok: false, error: 'PRECISION', message: `At most ${rules.decimals} decimal places allowed` };
  }
  const amount = new D(text);
  if (amount.lt(rules.minAmount)) {
    return { ok: false, error: 'BELOW_MIN', message: `Minimum amount is ${plain(rules.minAmount)}` };
  }
  if (amount.gt(rules.available)) {
    return { ok: false, error: 'ABOVE_AVAILABLE', message: `Exceeds available balance (${plain(rules.available)})` };
  }
  return { ok: true, amount, text };
}

export interface ClaimPreview {
  fee: Dec;
  receive: Dec;
}

/** The fee is taken from the claimed amount: user receives amount - fee. Exact decimal subtraction. */
export function claimPreview(amount: Dec, fee: string): ClaimPreview {
  const feeDec = new D(fee);
  return { fee: feeDec, receive: amount.minus(feeDec) };
}

export interface BalanceLike {
  available: string;
  usdPrice: string;
}

export function usdValue(amount: string, usdPrice: string): Dec {
  return new D(amount).times(usdPrice);
}

/** Total USD value of the claimable (`available`) balances. */
export function totalUsd(items: BalanceLike[]): Dec {
  return items.reduce<Dec>((sum, i) => sum.plus(usdValue(i.available, i.usdPrice)), new D(0));
}

/** Display-only rounding to cents (half-up) with thousands separators. Never fed back into maths. */
export function formatUsd(value: Dec): string {
  const fixed = new D(value).toFixed(2, Decimal.ROUND_HALF_UP);
  const [int, frac] = fixed.split('.');
  return `$${int.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}.${frac}`;
}

import { parseServerDecimal } from './money';

// Public, non-secret config. Overridable for local mock-server testing only.
export const API_BASE = process.env.EXPO_PUBLIC_API_BASE ?? 'https://task-api.cashmine.io';
const REQUEST_TIMEOUT_MS = 20000;

export interface BalanceItem {
  asset: string;
  decimals: number;
  available: string;
  pending: string;
  claiming: string;
  usdPrice: string;
}
export interface Balances {
  asOf: string;
  items: BalanceItem[];
}
export interface ClaimOptions {
  asset: string;
  minAmount: string;
  fee: string;
  destinations: { id: string; label: string }[];
}
export interface ClaimBody {
  asset: string;
  amount: string;
  destinationId: string;
}
export type ClaimStatus = 'pending' | 'completed' | 'failed';
export interface Claim {
  id: string;
  asset: string;
  amount: string;
  fee: string;
  receiveAmount: string;
  destinationId: string;
  status: ClaimStatus;
  failureReason: string | null;
  createdAt: string;
  updatedAt: string;
}

export class ApiError extends Error {
  constructor(
    public status: number, // 0 = no HTTP response (network failure / client timeout)
    public code: string,
    message: string,
    public field?: string,
    public retryAfterMs?: number,
  ) {
    super(message);
  }
  /** The request may or may not have been processed (safe to re-send only with the same idempotency key). */
  get outcomeUnknown(): boolean {
    return this.status === 0 || this.status >= 500;
  }
}

async function request<T>(
  method: 'GET' | 'POST',
  path: string,
  token: string,
  opts: { body?: unknown; headers?: Record<string, string> } = {},
): Promise<{ status: number; data: T }> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), REQUEST_TIMEOUT_MS);
  let res: Response;
  try {
    res = await fetch(`${API_BASE}${path}`, {
      method,
      signal: controller.signal,
      headers: {
        Authorization: `Bearer ${token}`,
        ...(opts.body !== undefined ? { 'Content-Type': 'application/json' } : {}),
        ...opts.headers,
      },
      body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined,
    });
  } catch (e) {
    const aborted = e instanceof Error && e.name === 'AbortError';
    throw new ApiError(0, aborted ? 'CLIENT_TIMEOUT' : 'NETWORK', aborted ? 'Request timed out' : 'Network error');
  } finally {
    clearTimeout(timer);
  }

  let json: any = null;
  try {
    json = await res.json();
  } catch {
    json = null;
  }
  if (!res.ok) {
    const err = json?.error ?? {};
    const headerRetry = Number(res.headers.get('Retry-After'));
    const retryAfterMs =
      typeof err.retryAfterMs === 'number' ? err.retryAfterMs : headerRetry > 0 ? headerRetry * 1000 : undefined;
    throw new ApiError(
      res.status,
      err.code ?? (res.status === 504 ? 'TIMEOUT' : 'SERVER'),
      err.message ?? `Request failed (${res.status})`,
      err.field,
      retryAfterMs,
    );
  }
  return { status: res.status, data: json as T };
}

// --- response parsing: reject anything that is not a decimal string (never JSON numbers) ---

export function parseBalances(raw: any): Balances {
  if (!raw || typeof raw.asOf !== 'string' || !Array.isArray(raw.items)) throw new Error('Unexpected balances response');
  return {
    asOf: raw.asOf,
    items: raw.items.map((i: any): BalanceItem => {
      if (typeof i?.asset !== 'string' || !Number.isInteger(i.decimals)) throw new Error('Unexpected balance item');
      for (const k of ['available', 'pending', 'claiming', 'usdPrice']) parseServerDecimal(i[k], `${i.asset}.${k}`);
      return {
        asset: i.asset,
        decimals: i.decimals,
        available: i.available,
        pending: i.pending,
        claiming: i.claiming,
        usdPrice: i.usdPrice,
      };
    }),
  };
}

export function parseClaimOptions(raw: any): ClaimOptions {
  if (!raw || typeof raw.asset !== 'string' || !Array.isArray(raw.destinations)) {
    throw new Error('Unexpected claim options response');
  }
  parseServerDecimal(raw.minAmount, 'minAmount');
  parseServerDecimal(raw.fee, 'fee');
  return { asset: raw.asset, minAmount: raw.minAmount, fee: raw.fee, destinations: raw.destinations };
}

export function parseClaim(raw: any): Claim {
  if (!raw || typeof raw.id !== 'string' || !['pending', 'completed', 'failed'].includes(raw.status)) {
    throw new Error('Unexpected claim response');
  }
  for (const k of ['amount', 'fee', 'receiveAmount']) parseServerDecimal(raw[k], k);
  return raw as Claim;
}

// --- endpoints ---

export async function getBalances(token: string): Promise<Balances> {
  return parseBalances((await request('GET', '/v1/balances', token)).data);
}

export async function getClaimOptions(token: string, asset: string): Promise<ClaimOptions> {
  return parseClaimOptions((await request('GET', `/v1/claim-options?asset=${encodeURIComponent(asset)}`, token)).data);
}

export async function createClaim(token: string, idempotencyKey: string, body: ClaimBody) {
  const res = await request('POST', '/v1/claims', token, { body, headers: { 'Idempotency-Key': idempotencyKey } });
  return { claim: parseClaim(res.data), replayed: res.status === 200 };
}

export async function getClaim(token: string, id: string): Promise<Claim> {
  return parseClaim((await request('GET', `/v1/claims/${encodeURIComponent(id)}`, token)).data);
}

// Thin localStorage wrapper. Falls back to memory when storage is unavailable (private mode etc.).
const memory = new Map<string, string>();

function read(key: string): string | null {
  try {
    return window.localStorage.getItem(key);
  } catch {
    return memory.get(key) ?? null;
  }
}
function write(key: string, value: string) {
  try {
    window.localStorage.setItem(key, value);
  } catch {
    memory.set(key, value);
  }
}
function remove(key: string) {
  try {
    window.localStorage.removeItem(key);
  } catch {
    memory.delete(key);
  }
}

const TOKEN_KEY = 'cashmine.token';
const ATTEMPT_KEY = 'cashmine.claimAttempt';

export const loadToken = () => read(TOKEN_KEY);
export const saveToken = (t: string) => write(TOKEN_KEY, t);
export const clearToken = () => remove(TOKEN_KEY);

export function loadJson<T>(): T | null {
  const raw = read(ATTEMPT_KEY);
  if (!raw) return null;
  try {
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
}
export const saveJson = (v: unknown) => write(ATTEMPT_KEY, JSON.stringify(v));
export const clearJson = () => remove(ATTEMPT_KEY);

/** Non-reversible-enough tag so a stored claim attempt is only resumed with the token that created it. */
export function tokenTag(token: string): string {
  let h = 5381;
  for (let i = 0; i < token.length; i++) h = ((h << 5) + h + token.charCodeAt(i)) >>> 0;
  return h.toString(16);
}

import React from 'react';
import { Pressable, StyleSheet, Text, View, ViewStyle } from 'react-native';

export const colors = {
  bg: '#f4f5f7',
  card: '#ffffff',
  text: '#111827',
  muted: '#6b7280',
  border: '#e5e7eb',
  primary: '#2563eb',
  danger: '#b91c1c',
  dangerBg: '#fee2e2',
  warnBg: '#fef3c7',
  warn: '#92400e',
  okBg: '#dcfce7',
  ok: '#166534',
  infoBg: '#dbeafe',
  info: '#1e3a8a',
};

export function Button(props: {
  label: string;
  onPress: () => void;
  kind?: 'primary' | 'secondary' | 'danger';
  disabled?: boolean;
  style?: ViewStyle;
}) {
  const kind = props.kind ?? 'primary';
  return (
    <Pressable
      accessibilityRole="button"
      onPress={props.onPress}
      disabled={props.disabled}
      style={[
        s.btn,
        kind === 'primary' && { backgroundColor: colors.primary },
        kind === 'danger' && { backgroundColor: colors.danger },
        kind === 'secondary' && { backgroundColor: colors.card, borderWidth: 1, borderColor: colors.border },
        props.disabled && { opacity: 0.45 },
        props.style,
      ]}
    >
      <Text style={[s.btnText, kind === 'secondary' && { color: colors.text }]}>{props.label}</Text>
    </Pressable>
  );
}

export function Card(props: { children: React.ReactNode; style?: ViewStyle }) {
  return <View style={[s.card, props.style]}>{props.children}</View>;
}

export function Banner(props: { tone: 'error' | 'warn' | 'ok' | 'info'; children: React.ReactNode }) {
  const t = {
    error: [colors.dangerBg, colors.danger],
    warn: [colors.warnBg, colors.warn],
    ok: [colors.okBg, colors.ok],
    info: [colors.infoBg, colors.info],
  }[props.tone];
  return (
    <View style={[s.banner, { backgroundColor: t[0] }]}>
      <Text style={{ color: t[1], fontSize: 14 }}>{props.children}</Text>
    </View>
  );
}

export const text = StyleSheet.create({
  h1: { fontSize: 22, fontWeight: '700', color: colors.text },
  h2: { fontSize: 17, fontWeight: '600', color: colors.text },
  body: { fontSize: 15, color: colors.text },
  muted: { fontSize: 13, color: colors.muted },
  mono: { fontSize: 13, color: colors.text, fontFamily: 'monospace' },
});

const s = StyleSheet.create({
  btn: { minHeight: 44, paddingHorizontal: 16, borderRadius: 10, alignItems: 'center', justifyContent: 'center' },
  btnText: { color: '#fff', fontWeight: '600', fontSize: 15 },
  card: {
    backgroundColor: colors.card,
    borderRadius: 12,
    borderWidth: 1,
    borderColor: colors.border,
    padding: 14,
    marginBottom: 12,
  },
  banner: { borderRadius: 10, padding: 12, marginBottom: 12 },
});

import { useCallback, useEffect, useRef, useState } from 'react';
import { ApiError, Balances, getBalances } from './lib/api';

/** Server-authoritative balances. Never mutated locally; only replaced by a fresh GET /v1/balances. */
export function useBalances(token: string, autoRefreshMs: number | null) {
  const [data, setData] = useState<Balances | null>(null);
  const [error, setError] = useState<ApiError | Error | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const seq = useRef(0);

  const refresh = useCallback(async () => {
    const id = ++seq.current;
    setRefreshing(true);
    try {
      const b = await getBalances(token);
      if (id === seq.current) {
        setData(b);
        setError(null);
      }
    } catch (e) {
      if (id === seq.current) setError(e as Error);
    } finally {
      if (id === seq.current) {
        setLoading(false);
        setRefreshing(false);
      }
    }
  }, [token]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  useEffect(() => {
    if (!autoRefreshMs) return;
    const t = setInterval(refresh, autoRefreshMs);
    return () => clearInterval(t);
  }, [refresh, autoRefreshMs]);

  return { data, error, loading, refreshing, refresh };
}

import React, { useState } from 'react';
import { StyleSheet, Text, TextInput, View } from 'react-native';
import { Banner, Button, Card, colors, text } from '../ui';

export function TokenScreen(props: {
  hasToken: boolean;
  onSave: (token: string) => void;
  onCancel: () => void;
  onForget: () => void;
}) {
  const [value, setValue] = useState('');
  const submit = () => {
    const t = value.trim();
    if (t) props.onSave(t);
  };
  return (
    <View>
      <Text style={text.h1}>{props.hasToken ? 'Change API token' : 'Enter your API token'}</Text>
      <Text style={[text.muted, { marginVertical: 8 }]}>
        The token from your task email. It is stored only in this browser (localStorage) and sent only to the CashMine
        API.
      </Text>
      <Card>
        <Text style={text.muted}>Bearer token</Text>
        <TextInput
          value={value}
          onChangeText={setValue}
          onSubmitEditing={submit}
          secureTextEntry
          autoCapitalize="none"
          autoCorrect={false}
          autoComplete="off"
          placeholder="Paste token"
          style={styles.input}
        />
        <Button label="Save token" onPress={submit} disabled={!value.trim()} />
      </Card>
      {props.hasToken && (
        <>
          <Banner tone="warn">A token is currently saved. Saving a new one replaces it.</Banner>
          <Button label="Cancel" kind="secondary" onPress={props.onCancel} style={{ marginBottom: 8 }} />
          <Button label="Forget saved token" kind="danger" onPress={props.onForget} />
        </>
      )}
    </View>
  );
}

const styles = StyleSheet.create({
  input: {
    borderWidth: 1,
    borderColor: colors.border,
    borderRadius: 10,
    paddingHorizontal: 12,
    height: 44,
    fontSize: 16,
    marginVertical: 10,
    color: colors.text,
  },
});

import React, { useEffect, useState } from 'react';
import { ActivityIndicator, Text, View } from 'react-native';
import { ApiError, Balances } from '../lib/api';
import { formatUsd, plain, totalUsd, usdValue } from '../lib/money';
import { Banner, Button, Card, colors, text } from '../ui';

function useNow(intervalMs = 1000) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), intervalMs);
    return () => clearInterval(t);
  }, [intervalMs]);
  return now;
}

function ago(ms: number) {
  const s = Math.max(0, Math.round(ms / 1000));
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ${s % 60}s ago`;
  return `${Math.floor(s / 3600)}h ago`;
}

export function BalancesScreen(props: {
  data: Balances | null;
  error: Error | null;
  loading: boolean;
  refreshing: boolean;
  onRefresh: () => void;
  onClaim: (asset: string) => void;
  onChangeToken: () => void;
  claimInProgress: boolean;
}) {
  const now = useNow();
  const { data, error } = props;
  const unauthorized = error instanceof ApiError && error.status === 401;

  if (props.loading && !data) {
    return (
      <View style={{ padding: 32, alignItems: 'center' }}>
        <ActivityIndicator />
        <Text style={[text.muted, { marginTop: 8 }]}>Loading balances…</Text>
      </View>
    );
  }

  const age = data ? now - new Date(data.asOf).getTime() : 0;

  return (
    <View>
      {error && (
        <Banner tone="error">
          {unauthorized
            ? 'Your token is missing, invalid or expired. Change the token to continue.'
            : `Could not load balances: ${error.message}.${data ? ' Showing the last successful snapshot.' : ''}`}
        </Banner>
      )}
      {error && unauthorized && <Button label="Change token" onPress={props.onChangeToken} style={{ marginBottom: 12 }} />}
      {error && !unauthorized && (
        <Button label="Retry" kind="secondary" onPress={props.onRefresh} disabled={props.refreshing} style={{ marginBottom: 12 }} />
      )}

      {data && (
        <>
          <Card>
            <Text style={text.muted}>Total claimable (available) value</Text>
            <Text style={{ fontSize: 30, fontWeight: '700', color: colors.text, marginVertical: 4 }}>
              {formatUsd(totalUsd(data.items))}
            </Text>
            <Text style={[text.muted, age > 45000 && { color: colors.warn, fontWeight: '600' }]}>
              Snapshot as of {new Date(data.asOf).toLocaleTimeString()} ({ago(age)}
              {age > 45000 ? ' – may be outdated' : ''})
            </Text>
            <Button
              label={props.refreshing ? 'Refreshing…' : 'Refresh'}
              kind="secondary"
              onPress={props.onRefresh}
              disabled={props.refreshing}
              style={{ marginTop: 10 }}
            />
          </Card>

          {props.claimInProgress && (
            <Banner tone="info">
              A claim is in progress. Balances are server snapshots (refreshed about every 15 s), so the claim may not
              be reflected here yet.
            </Banner>
          )}

          {data.items.length === 0 && <Text style={text.muted}>No assets yet.</Text>}
          {data.items.map((i) => (
            <Card key={i.asset}>
              <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'baseline' }}>
                <Text style={text.h2}>{i.asset}</Text>
                <Text style={text.muted}>${plain(i.usdPrice)} / unit</Text>
              </View>
              <Text style={{ fontSize: 22, fontWeight: '700', color: colors.text, marginTop: 6 }}>
                {plain(i.available)} <Text style={text.muted}>available</Text>
              </Text>
              <Text style={text.muted}>≈ {formatUsd(usdValue(i.available, i.usdPrice))}</Text>
              <View style={{ marginTop: 6 }}>
                <Text style={text.muted}>Pending (unconfirmed): {plain(i.pending)}</Text>
                <Text style={text.muted}>Claiming (in unfinished claims): {plain(i.claiming)}</Text>
              </View>
              <Button label={`Claim ${i.asset}`} onPress={() => props.onClaim(i.asset)} style={{ marginTop: 10 }} />
            </Card>
          ))}
        </>
      )}
    </View>
  );
}

import React, { useState } from 'react';
import { SafeAreaView, ScrollView, StyleSheet, Text, View } from 'react-native';
import { StatusBar } from 'expo-status-bar';
import { clearToken, loadToken, saveToken } from './src/lib/storage';
import { BalancesScreen } from './src/screens/BalancesScreen';
import { TokenScreen } from './src/screens/TokenScreen';
import { useBalances } from './src/useBalances';
import { Button, colors, text } from './src/ui';

export default function App() {
  const [token, setToken] = useState<string | null>(() => loadToken());
  const [editingToken, setEditingToken] = useState(false);

  return (
    <SafeAreaView style={styles.root}>
      <StatusBar style="dark" />
      <ScrollView contentContainerStyle={styles.scroll} keyboardShouldPersistTaps="handled">
        <View style={styles.column}>
          {!token || editingToken ? (
            <TokenScreen
              hasToken={!!token}
              onSave={(t) => {
                saveToken(t);
                setToken(t);
                setEditingToken(false);
              }}
              onCancel={() => setEditingToken(false)}
              onForget={() => {
                clearToken();
                setToken(null);
                setEditingToken(false);
              }}
            />
          ) : (
            <Main token={token} onChangeToken={() => setEditingToken(true)} />
          )}
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

function Main(props: { token: string; onChangeToken: () => void }) {
  const balances = useBalances(props.token, null);
  return (
    <View>
      <View style={styles.header}>
