// Local mock of the CashMine task API for UI testing without a real token. Not used in production.
// Modes (env MODE): normal | lose-first (first POST creates the claim but replies 504) | always-504
import http from 'node:http';

const MODE = process.env.MODE ?? 'normal';
const claims = new Map(); // id -> claim
const keys = new Map(); // idempotency key -> { body, id }
let available = 820.5;
let n = 0;

const send = (res, status, json, headers = {}) => {
  res.writeHead(status, {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': '*',
    'Access-Control-Expose-Headers': 'Idempotent-Replayed',
    ...headers,
  });
  res.end(JSON.stringify(json));
};

http
  .createServer((req, res) => {
    if (req.method === 'OPTIONS') return send(res, 204, {});
    if (req.headers.authorization !== 'Bearer <redacted-token>') {
      return send(res, 401, { error: { code: 'UNAUTHORIZED', message: 'Invalid token' } });
    }
    const url = new URL(req.url, 'http://x');
    if (url.pathname === '/v1/balances') {
      const claiming = [...claims.values()].filter((c) => c.status === 'pending').reduce((s, c) => s + Number(c.amount), 0);
      return send(res, 200, {
        asOf: new Date().toISOString(),
        items: [
          { asset: 'USDT', decimals: 6, available: available.toFixed(6), pending: '50.12', claiming: String(claiming), usdPrice: '1.0002' },
          { asset: 'ETH', decimals: 18, available: '1.25', pending: '0', claiming: '0', usdPrice: '3200.5' },
        ],
      });
    }
    if (url.pathname === '/v1/claim-options') {
      return send(res, 200, {
        asset: url.searchParams.get('asset'),
        minAmount: '0.01',
        fee: '0.0012',
        destinations: [{ id: 'dest_wallet', label: 'Wallet 0x8f3e…a91c' }],
      });
    }
    if (url.pathname === '/v1/claims' && req.method === 'POST') {
      let raw = '';
      req.on('data', (c) => (raw += c));
      req.on('end', () => {
        const key = req.headers['idempotency-key'];
        const body = JSON.parse(raw);
        const prior = keys.get(key);
        if (prior) {
          if (JSON.stringify(prior.body) !== JSON.stringify(body)) {
            return send(res, 409, { error: { code: 'IDEMPOTENCY_MISMATCH', message: 'Key reused with different body' } });
          }
          return send(res, 200, claims.get(prior.id), { 'Idempotent-Replayed': 'true' });
        }
        const amount = Number(body.amount);
        if (amount > available) return send(res, 400, { error: { code: 'VALIDATION', message: 'Insufficient balance', field: 'amount' } });
        const id = `clm_${++n}`;
        const claim = {
          id, asset: body.asset, amount: body.amount, fee: '0.0012',
          receiveAmount: (amount - 0.0012).toFixed(4), destinationId: body.destinationId,
          status: 'pending', failureReason: null, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(),
        };
        claims.set(id, claim);
        keys.set(key, { body, id });
        available -= amount;
        setTimeout(() => {
          claim.status = amount === 13 ? 'failed' : 'completed';
          if (claim.status === 'failed') {
            claim.failureReason = 'Destination rejected the transfer';
            available += amount;
          }
        }, 8000);
        if (MODE === 'always-504' || (MODE === 'lose-first' && keys.size === 1 && !globalThis.__lost)) {
          globalThis.__lost = true;
          return send(res, 504, { error: { code: 'TIMEOUT', message: 'Timed out' } });
        }
        send(res, 201, claim);
      });
      return;
    }
    const m = url.pathname.match(/^\/v1\/claims\/(.+)$/);
    if (m) return claims.has(m[1]) ? send(res, 200, claims.get(m[1])) : send(res, 404, { error: { code: 'NOT_FOUND', message: 'Unknown id' } });
    send(res, 404, { error: { code: 'NOT_FOUND', message: 'Unknown endpoint' } });
  })
  .listen(8787, () => console.log(`mock api on :8787 mode=${MODE}`));

import { Claim } from './api';

/**
 * Balance-sync policy. A claim's status (GET /claims/{id}) is authoritative for the claim, but the balances
 * snapshot may still be older than the settlement. After a claim reaches a terminal state we therefore keep a
 * "gate" until a snapshot that is provably newer than the settlement has been read from the server.
 * No amount is ever computed or overwritten locally; the gate only drives messaging and blocks NEW claims.
 */
export interface SyncGate {
  claimId: string;
  observedAt: number; // client time (ms) when we first saw the terminal status
  minAsOf: number; // snapshot must be newer than this (server time, ms)
}

export function makeGate(claim: Claim, currentAsOf: string | null, now: number): SyncGate {
  const t = (s: string | null | undefined) => {
    const v = s ? Date.parse(s) : NaN;
    return Number.isNaN(v) ? 0 : v;
  };
  // Newer than both the claim's last server update and the snapshot we were already showing.
  return { claimId: claim.id, observedAt: now, minAsOf: Math.max(t(claim.updatedAt), t(currentAsOf)) };
}

/**
 * Reconciled once a SUCCESSFUL balances fetch that started after we observed the settlement returned a snapshot
 * whose `asOf` is newer than the gate's threshold. Failed fetches (e.g. 503) never reconcile.
 */
export function isReconciled(gate: SyncGate, snap: { okStartedAt: number | null; asOf: string | null }): boolean {
  if (snap.okStartedAt === null || !snap.asOf) return false;
  const asOf = Date.parse(snap.asOf);
  if (Number.isNaN(asOf)) return false;
  return snap.okStartedAt >= gate.observedAt && asOf > gate.minAsOf;
}

import { describe, expect, it } from 'vitest';
import { Claim } from '../api';
import { isReconciled, makeGate } from '../sync';

const claim = { id: 'clm_1', updatedAt: '2026-10-22T07:00:10.000Z' } as Claim;
const T = (s: string) => Date.parse(`2026-10-22T${s}.000Z`);

describe('balance sync gate', () => {
  const gate = makeGate(claim, '2026-10-22T07:00:05.000Z', T('07:00:12'));

  it('uses the newer of claim.updatedAt and the snapshot already shown', () => {
    expect(gate.minAsOf).toBe(T('07:00:10'));
    expect(makeGate(claim, '2026-10-22T07:00:20.000Z', 0).minAsOf).toBe(T('07:00:20'));
    expect(makeGate(claim, null, 0).minAsOf).toBe(T('07:00:10'));
  });

  it('is not reconciled without a successful fetch (e.g. refresh returned 503)', () => {
    expect(isReconciled(gate, { okStartedAt: null, asOf: null })).toBe(false);
  });

  it('is not reconciled by the old snapshot, even if re-fetched later', () => {
    expect(isReconciled(gate, { okStartedAt: T('07:00:13'), asOf: '2026-10-22T07:00:05.000Z' })).toBe(false);
    expect(isReconciled(gate, { okStartedAt: T('07:00:13'), asOf: '2026-10-22T07:00:10.000Z' })).toBe(false);
  });

  it('is not reconciled by a fetch that started before the settlement was observed', () => {
    expect(isReconciled(gate, { okStartedAt: T('07:00:11'), asOf: '2026-10-22T07:00:15.000Z' })).toBe(false);
  });

  it('is reconciled by a later successful fetch with a newer snapshot', () => {
    expect(isReconciled(gate, { okStartedAt: T('07:00:13'), asOf: '2026-10-22T07:00:15.000Z' })).toBe(true);
  });

  it('treats an unparsable asOf as not reconciled', () => {
    expect(isReconciled(gate, { okStartedAt: T('07:00:13'), asOf: 'garbage' })).toBe(false);
  });
});

import { useCallback, useEffect, useRef, useState } from 'react';
import { ApiError, Balances, getBalances } from './lib/api';

/** Server-authoritative balances. Never mutated locally; only replaced by a fresh GET /v1/balances. */
export function useBalances(token: string, autoRefreshMs: number | null) {
  const [data, setData] = useState<Balances | null>(null);
  const [error, setError] = useState<ApiError | Error | null>(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  // Client time at which the request that produced `data` was started (used by the sync policy).
  const [okStartedAt, setOkStartedAt] = useState<number | null>(null);
  const seq = useRef(0);

  const refresh = useCallback(async () => {
    const id = ++seq.current;
    const startedAt = Date.now();
    setRefreshing(true);
    try {
      const b = await getBalances(token);
      if (id === seq.current) {
        setData(b);
        setOkStartedAt(startedAt);
        setError(null);
      }
    } catch (e) {
      if (id === seq.current) setError(e as Error);
    } finally {
      if (id === seq.current) {
        setLoading(false);
        setRefreshing(false);
      }
    }
  }, [token]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  useEffect(() => {
    if (!autoRefreshMs) return;
    const t = setInterval(refresh, autoRefreshMs);
    return () => clearInterval(t);
  }, [refresh, autoRefreshMs]);

  return { data, error, loading, refreshing, okStartedAt, refresh };
}

import React, { useEffect, useState } from 'react';
import { ActivityIndicator, Text, View } from 'react-native';
import { ApiError, Balances } from '../lib/api';
import { formatUsd, plain, totalUsd, usdValue } from '../lib/money';
import { Banner, Button, Card, colors, text } from '../ui';

function useNow(intervalMs = 1000) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), intervalMs);
    return () => clearInterval(t);
  }, [intervalMs]);
  return now;
}

function ago(ms: number) {
  const s = Math.max(0, Math.round(ms / 1000));
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ${s % 60}s ago`;
  return `${Math.floor(s / 3600)}h ago`;
}

export function BalancesScreen(props: {
  data: Balances | null;
  error: Error | null;
  loading: boolean;
  refreshing: boolean;
  onRefresh: () => void;
  onClaim: (asset: string) => void;
  onChangeToken: () => void;
  claimInProgress: boolean;
  syncing: boolean; // a settled claim is not yet reconciled with a newer server snapshot
}) {
  const now = useNow();
  const { data, error } = props;
  const unauthorized = error instanceof ApiError && error.status === 401;

  if (props.loading && !data) {
    return (
      <View style={{ padding: 24, alignItems: 'center' }}>
        <ActivityIndicator />
        <Text style={[text.muted, { marginTop: 8 }]}>Loading balances…</Text>
      </View>
    );
  }

  const age = data ? now - new Date(data.asOf).getTime() : 0;
  const stale = props.claimInProgress || props.syncing;

  return (
    <View>
      {error && (
        <Banner tone="error">
          {unauthorized
            ? 'Your token is missing, invalid or expired.'
            : `Could not refresh balances: ${error.message}.${data ? ' Showing the last snapshot; retrying automatically while a claim is syncing.' : ''}`}
        </Banner>
      )}
      {unauthorized && <Button label="Change token" onPress={props.onChangeToken} style={{ marginBottom: 8 }} />}
      {/* The only Retry/Refresh control lives in the total card; this covers the "no snapshot yet" case. */}
      {error && !unauthorized && !data && (
        <Button label="Retry" onPress={props.onRefresh} disabled={props.refreshing} style={{ marginBottom: 8 }} />
      )}

