import React from 'react';
import { Pressable, StyleSheet, Text, View, ViewStyle } from 'react-native';

// Light fintech palette: ink + lime accent, soft tinted states. Presentation only.
export const colors = {
  bg: '#F3F4F6',
  card: '#FFFFFF',
  text: '#0E0F0C',
  muted: '#60646C',
  faint: '#9AA0A8',
  border: '#E6E8EC',
  soft: '#EEF0F3',
  primary: '#0E0F0C',
  link: '#1F5FE0',
  accent: '#9FE870',
  accentInk: '#163300',
  danger: '#C62B33',
  dangerBg: '#FDECEC',
  warnBg: '#FFF3D4',
  warn: '#8A5A00',
  okBg: '#E2F6E9',
  ok: '#0B7A3E',
  infoBg: '#E8EEFD',
  info: '#2A4FB8',
};

export const num = { fontVariant: ['tabular-nums' as const] };

export function Button(props: {
  label: string;
  onPress: () => void;
  kind?: 'primary' | 'accent' | 'secondary' | 'danger' | 'link';
  size?: 'md' | 'sm';
  disabled?: boolean;
  style?: ViewStyle;
}) {
  const kind = props.kind ?? 'primary';
  const sm = props.size === 'sm';
  const fg = { primary: '#fff', accent: colors.accentInk, secondary: colors.text, danger: '#fff', link: colors.link }[kind];
  const bg = {
    primary: colors.primary,
    accent: colors.accent,
    secondary: colors.soft,
    danger: colors.danger,
    link: 'transparent',
  }[kind];
  return (
    <Pressable
      accessibilityRole="button"
      onPress={props.onPress}
      disabled={props.disabled}
      style={({ pressed }) => [
        s.btn,
        sm && s.btnSm,
        { backgroundColor: bg },
        pressed && { opacity: 0.8 },
        props.disabled && { opacity: 0.4 },
        props.style,
      ]}
    >
      <Text style={{ color: fg, fontWeight: '700', fontSize: sm ? 14 : 16 }}>{props.label}</Text>
    </Pressable>
  );
}

export function Card(props: { children: React.ReactNode; style?: ViewStyle }) {
  return <View style={[s.card, props.style]}>{props.children}</View>;
}

/** Soft, compact notice. Used sparingly; routine states use inline lines or status rows instead. */
export function Banner(props: { tone: 'error' | 'warn' | 'ok' | 'info'; children: React.ReactNode }) {
  const t = {
    error: [colors.dangerBg, colors.danger],
    warn: [colors.warnBg, colors.warn],
    ok: [colors.okBg, colors.ok],
    info: [colors.infoBg, colors.info],
  }[props.tone];
  return (
    <View style={[s.banner, { backgroundColor: t[0] }]}>
      <View style={[s.dot, { backgroundColor: t[1] }]} />
      <Text style={{ color: t[1], fontSize: 13, lineHeight: 18, flex: 1 }}>{props.children}</Text>
    </View>
  );
}

const AVATARS = [
  ['#E3EEFF', '#1F4FBF'],
  ['#FFEFD6', '#9A5B00'],
  ['#E6F6E8', '#17703A'],
  ['#F3E8FF', '#6B2FB3'],
  ['#FFE8EC', '#B3243D'],
];
export function Avatar(props: { asset: string; size?: number }) {
  const size = props.size ?? 40;
  let h = 0;
  for (const ch of props.asset) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  const [bg, fg] = AVATARS[h % AVATARS.length];
  return (
    <View style={{ width: size, height: size, borderRadius: size / 2, backgroundColor: bg, alignItems: 'center', justifyContent: 'center' }}>
      <Text style={{ color: fg, fontWeight: '800', fontSize: size * 0.34 }}>{props.asset.slice(0, 2)}</Text>
    </View>
  );
}

export const text = StyleSheet.create({
  h1: { fontSize: 26, fontWeight: '800', color: colors.text, letterSpacing: -0.5 },
  h2: { fontSize: 17, fontWeight: '700', color: colors.text },
  body: { fontSize: 15, color: colors.text },
  muted: { fontSize: 13, color: colors.muted },
  label: { fontSize: 12, fontWeight: '600', color: colors.muted, letterSpacing: 0.3 },
  mono: { fontSize: 13, color: colors.text, fontFamily: 'monospace' },
});

const s = StyleSheet.create({
  btn: { minHeight: 52, paddingHorizontal: 20, borderRadius: 16, alignItems: 'center', justifyContent: 'center' },
  btnSm: { minHeight: 34, paddingHorizontal: 14, borderRadius: 17 },
  card: {
    backgroundColor: colors.card,
    borderRadius: 20,
    padding: 16,
    marginBottom: 12,
  },
  banner: { borderRadius: 14, paddingVertical: 10, paddingHorizontal: 12, marginBottom: 10, flexDirection: 'row', gap: 10, alignItems: 'flex-start' },
  dot: { width: 8, height: 8, borderRadius: 4, marginTop: 5 },
});

import React, { useEffect, useState } from 'react';
import { ActivityIndicator, Pressable, Text, View } from 'react-native';
import { ApiError, Balances } from '../lib/api';
import { D, formatUsd, plain, totalUsd, usdValue } from '../lib/money';
import { Avatar, Banner, Button, Card, colors, num, text } from '../ui';

function useNow(intervalMs = 1000) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), intervalMs);
    return () => clearInterval(t);
  }, [intervalMs]);
  return now;
}

function ago(ms: number) {
  const s = Math.max(0, Math.round(ms / 1000));
  if (s < 60) return `${s}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ${s % 60}s ago`;
  return `${Math.floor(s / 3600)}h ago`;
}

function Chip(props: { label: string; tone?: 'warn' }) {
  return (
    <View style={{ backgroundColor: props.tone === 'warn' ? colors.warnBg : colors.soft, borderRadius: 10, paddingHorizontal: 8, paddingVertical: 3 }}>
      <Text style={[{ fontSize: 12, fontWeight: '600', color: props.tone === 'warn' ? colors.warn : colors.muted }, num]}>{props.label}</Text>
    </View>
  );
}

export function BalancesScreen(props: {
  data: Balances | null;
  error: Error | null;
  loading: boolean;
  refreshing: boolean;
  onRefresh: () => void;
  onClaim: (asset: string) => void;
  onChangeToken: () => void;
  claimInProgress: boolean;
  syncing: boolean; // a settled claim is not yet reconciled with a newer server snapshot
}) {
  const now = useNow();
  const { data, error } = props;
  const unauthorized = error instanceof ApiError && error.status === 401;

  if (props.loading && !data) {
    return (
      <View style={{ padding: 40, alignItems: 'center' }}>
        <ActivityIndicator />
        <Text style={[text.muted, { marginTop: 8 }]}>Loading balances…</Text>
      </View>
    );
  }

  const age = data ? now - new Date(data.asOf).getTime() : 0;
  const stale = props.claimInProgress || props.syncing;
  const outdated = age > 45000;
  const dot = stale || outdated || error ? '#F5B83D' : colors.accent;

  return (
    <View>
      {error && (
        <Banner tone="error">
          {unauthorized
            ? 'Your token is missing, invalid or expired.'
            : `Could not refresh balances: ${error.message}.${data ? ' Showing the last snapshot; retrying automatically while a claim is syncing.' : ''}`}
        </Banner>
      )}
      {unauthorized && <Button label="Change token" onPress={props.onChangeToken} style={{ marginBottom: 12 }} />}
      {/* The only Retry/Refresh control lives in the hero card; this covers the "no snapshot yet" case. */}
      {error && !unauthorized && !data && (
        <Button label="Retry" onPress={props.onRefresh} disabled={props.refreshing} style={{ marginBottom: 12 }} />
      )}

      {data && (
        <>
          <View style={{ backgroundColor: colors.primary, borderRadius: 24, padding: 20, marginBottom: 12 }}>
            <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' }}>
              <Text style={{ color: '#B8BDC4', fontSize: 13, fontWeight: '600' }}>Total claimable</Text>
              <Pressable
                onPress={props.onRefresh}
                disabled={props.refreshing}
                accessibilityRole="button"
                style={{ backgroundColor: 'rgba(255,255,255,0.14)', borderRadius: 16, paddingHorizontal: 12, paddingVertical: 6, opacity: props.refreshing ? 0.6 : 1 }}
              >
                <Text style={{ color: '#fff', fontSize: 13, fontWeight: '700' }}>
                  {props.refreshing ? 'Refreshing…' : error ? 'Retry' : '↻ Refresh'}
                </Text>
              </Pressable>
            </View>
            <Text style={[{ fontSize: 38, fontWeight: '800', color: '#fff', letterSpacing: -1, marginTop: 6 }, num]}>
              {formatUsd(totalUsd(data.items))}
            </Text>
            <View style={{ flexDirection: 'row', alignItems: 'center', marginTop: 10 }}>
              <View style={{ width: 8, height: 8, borderRadius: 4, backgroundColor: dot, marginRight: 8 }} />
              <Text style={{ color: '#B8BDC4', fontSize: 12, flex: 1 }}>
                Updated {ago(age)} · {new Date(data.asOf).toLocaleTimeString()}
                {outdated ? ' · may be outdated' : ''}
              </Text>
            </View>
            {stale && (
              <Text style={{ color: '#F5D58A', fontSize: 12, marginTop: 6, lineHeight: 17 }}>
                {props.claimInProgress
                  ? 'Claim in progress — this snapshot may not include it yet.'
                  : 'Balance syncing — waiting for a snapshot newer than your claim. Figures may be outdated.'}
              </Text>
            )}
          </View>

          <Text style={[text.label, { marginLeft: 4, marginBottom: 8 }]}>ASSETS</Text>
          {data.items.length === 0 && <Text style={text.muted}>No assets yet.</Text>}
          <Card style={{ paddingVertical: 4, paddingHorizontal: 16 }}>
            {data.items.map((i, idx) => {
              const hasPending = new D(i.pending).gt(0);
              const hasClaiming = new D(i.claiming).gt(0);
              return (
                <View
                  key={i.asset}
                  style={{ paddingVertical: 14, borderTopWidth: idx === 0 ? 0 : 1, borderTopColor: colors.border }}
                >
                  <View style={{ flexDirection: 'row', alignItems: 'center' }}>
                    <Avatar asset={i.asset} />
                    <View style={{ flex: 1, marginLeft: 12 }}>
                      <Text style={text.h2}>{i.asset}</Text>
                      <Text style={[text.muted, num]}>${plain(i.usdPrice)}</Text>
                    </View>
                    <View style={{ alignItems: 'flex-end' }}>
                      <Text style={[{ fontSize: 17, fontWeight: '700', color: colors.text }, num]}>
                        {plain(i.available)} {i.asset}
                      </Text>
                      <Text style={[text.muted, num]}>≈ {formatUsd(usdValue(i.available, i.usdPrice))}</Text>
                    </View>
                  </View>
                  <View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', marginTop: 10 }}>
                    <View style={{ flexDirection: 'row', flexWrap: 'wrap', gap: 6, flex: 1, marginRight: 8 }}>
                      {hasPending && <Chip label={`Pending ${plain(i.pending)} ${i.asset}`} />}
                      {hasClaiming && (
                        <Chip label={`Claiming ${plain(i.claiming)} ${i.asset}${stale ? ' · may be outdated' : ''}`} tone="warn" />
                      )}
                    </View>
                    <Button label="Claim" kind="accent" size="sm" onPress={() => props.onClaim(i.asset)} />
                  </View>
                </View>
              );
            })}
          </Card>
        </>
      )}
    </View>
  );
}

import React from 'react';
import { ActivityIndicator, Pressable, Text, View } from 'react-native';
import { ClaimAttempt } from '../lib/claimFlow';
import { plain } from '../lib/money';
import { Button, Card, colors, num, text } from '../ui';

function Badge(props: { kind: 'spin' | 'ok' | 'fail' | 'warn' }) {
  const map = {
    spin: { bg: colors.soft, fg: colors.muted, glyph: '' },
    ok: { bg: colors.okBg, fg: colors.ok, glyph: '✓' },
    fail: { bg: colors.dangerBg, fg: colors.danger, glyph: '!' },
    warn: { bg: colors.warnBg, fg: colors.warn, glyph: '?' },
  }[props.kind];
  return (
    <View style={{ width: 36, height: 36, borderRadius: 18, backgroundColor: map.bg, alignItems: 'center', justifyContent: 'center' }}>
      {props.kind === 'spin' ? <ActivityIndicator size="small" /> : <Text style={{ color: map.fg, fontWeight: '800', fontSize: 16 }}>{map.glyph}</Text>}
    </View>
  );
}

/**
 * Claim state, kept apart from the balance snapshot: the claim line is confirmed by GET /claims/{id};
 * the "Balances" line says whether the snapshot below has caught up yet.
 */
export function ClaimStatus(props: {
  attempt: ClaimAttempt;
  busy: boolean;
  pollError: Error | null;
  syncing: boolean;
  balanceError: Error | null;
  onRecheck: () => void;
  onDismiss: () => void;
}) {
  const { attempt, busy } = props;
  const claim = attempt.claim;
  const amount = `${plain(attempt.body.amount)} ${attempt.body.asset}`;

  if (attempt.phase === 'sending') {
    return (
      <Card style={{ padding: 14 }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12 }}>
          <Badge kind="spin" />
          <View style={{ flex: 1 }}>
            <Text style={[text.h2, num]}>Submitting {amount}…</Text>
            <Text style={text.muted}>Keep this page open. The request is protected against duplicates.</Text>
          </View>
        </View>
      </Card>
    );
  }
  if (attempt.phase === 'unknown') {
    return (
      <Card style={{ padding: 14, backgroundColor: colors.warnBg }}>
        <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12 }}>
          <Badge kind="warn" />
          <View style={{ flex: 1 }}>
            <Text style={[text.h2, { color: colors.warn }]}>Claim status unknown</Text>
            <Text style={{ color: colors.warn, fontSize: 13, lineHeight: 18 }}>
              We couldn’t confirm whether your {amount} claim was received. Checking again re-sends the same request with
              the same key, so it can’t be applied twice. New claims are paused until this is resolved.
            </Text>
          </View>
        </View>
        <Button label={busy ? 'Checking…' : 'Check again'} onPress={props.onRecheck} disabled={busy} size="sm" style={{ marginTop: 10, alignSelf: 'flex-start' }} />
      </Card>
    );
  }
  if (!claim) return null;

  const terminal = attempt.phase === 'done';
  const unit = claim.asset;
  const kind = claim.status === 'completed' ? 'ok' : claim.status === 'failed' ? 'fail' : 'spin';
  const label = { pending: 'Pending', completed: 'Completed', failed: 'Failed' }[claim.status];
  const tone = claim.status === 'completed' ? colors.ok : claim.status === 'failed' ? colors.danger : colors.muted;

  return (
    <Card style={{ padding: 14 }}>
      <View style={{ flexDirection: 'row', alignItems: 'center', gap: 12 }}>
        <Badge kind={kind} />
        <View style={{ flex: 1 }}>
          <Text style={[text.h2, num]}>
            Claim of {plain(claim.amount)} {unit}
          </Text>
          <Text style={{ fontSize: 13, fontWeight: '700', color: tone }}>
            {label}
            <Text style={{ fontWeight: '400', color: colors.muted }}>
              {claim.status === 'pending'
                ? ` · settles in about 20 s${props.pollError ? ' · status check failed, retrying…' : ''}`
                : terminal
                  ? ' · confirmed by server'
                  : ''}
            </Text>
          </Text>
        </View>
        {terminal && (
          <Pressable onPress={props.onDismiss} accessibilityRole="button" accessibilityLabel="Dismiss" hitSlop={10}>
            <Text style={{ color: colors.faint, fontSize: 22, paddingHorizontal: 4 }}>×</Text>
          </Pressable>
        )}
      </View>

      <View style={{ flexDirection: 'row', justifyContent: 'space-between', marginTop: 10 }}>
        <Text style={[text.muted, num]}>
          Fee {plain(claim.fee)} {unit}
        </Text>
        <Text style={[{ fontSize: 13, fontWeight: '700', color: colors.text }, num]}>
          You receive {plain(claim.receiveAmount)} {unit}
        </Text>
      </View>

      {claim.status === 'failed' && (
        <Text style={{ color: colors.danger, fontSize: 13, marginTop: 6 }}>
          {claim.failureReason ? `${claim.failureReason}. ` : ''}The amount returns to your available balance.
        </Text>
      )}
      {terminal && (
        <View style={{ flexDirection: 'row', alignItems: 'center', marginTop: 8 }}>
          <View style={{ width: 7, height: 7, borderRadius: 4, marginRight: 7, backgroundColor: props.syncing ? '#F5B83D' : colors.accent }} />
          <Text style={{ color: colors.muted, fontSize: 12, flex: 1, lineHeight: 16 }}>
            {props.syncing
              ? `Balances syncing — the figures below may still show this claim under “Claiming” or an outdated available amount.${
                  props.balanceError ? ' Last refresh failed; retrying…' : ''
                }`
              : 'Balances updated from the server.'}
          </Text>
        </View>
      )}
      <Text style={[text.muted, { fontSize: 11, color: colors.faint, marginTop: 6 }]}>ID {claim.id}</Text>
    </Card>
  );
}

